-- Schema for table: school_classes
CREATE TABLE IF NOT EXISTS "school_classes" (
    "id" INTEGER NOT NULL DEFAULT nextval('school_classes_id_seq'::regclass),
    "name" TEXT NOT NULL,
    "academic_year" TEXT,
    "metadata" JSONB,
    "created_at" TIMESTAMPTZ NOT NULL DEFAULT now(),
    "updated_at" TIMESTAMPTZ NOT NULL DEFAULT now(),
    CONSTRAINT "school_classes_pkey" PRIMARY KEY (id),
    CONSTRAINT "school_classes_name_key" UNIQUE (name)
);

-- Data for table: school_classes
SELECT setval('public.school_classes_id_seq', COALESCE((SELECT MAX("id") FROM "school_classes"), 1), TRUE);

